 * premium -- never against the policy total.
 */
public final class ItemRiskSurcharges {

    /**
     * One MHPCO risk surcharge: the risk it answers to, and the percentage it
     * adds to the base premium of each item carrying that risk.
     */
    private record RiskSurcharge(Predicate<Item> carriesTheRisk, int surchargePercent) {

